css:
.container {
  width: 300px;
  height: 340px;
  border-radius: 1em;
  overflow: hidden;
  box-shadow: 0 10px 20px #dbdbdb;
  font-family: sans-serif;
  background: white;
  pointer-events: none;
}

.palette {
  position: relative;
  width: 300px;
  height: 300px;
  border-radius: 1rem;
  overflow: hidden;
  pointer-events: auto;
}

.palette:hover > #color-code {
  opacity: 0;
}

.color {
  position: absolute;
  width: 300px;
  height: 300px;
  transform-origin: center;
  transition: 0.3s ease-in-out;
  box-sizing: inline-block;
  display: flex;
  align-items: center;
  justify-content: center;
}

.color span {
  color: white;
  font-weight: 600;
  letter-spacing: 1px;
}

#color1 {
  background: #4B0082;
  rotate: 45deg;
  translate: 212.13px 0;
  outline: 0 solid #4B0082;
  z-index: 9;
}

#color1:hover {
  translate: 0 0;
  rotate: 0deg;
  z-index: 99;
  outline: 20px solid #4B0082;
}

#color2 {
  background: #8A2BE2;
  rotate: 45deg;
  translate: 0 212.13px;
  outline: 0 solid #8A2BE2;
  z-index: 9;
}

#color2:hover {
  translate: 0 0;
  rotate: 0deg;
  z-index: 99;
  outline: 20px solid #8A2BE2;
}

#color2 span {
  color: #1A1A1A;
}

#color3 {
  background: #9932CC;
  rotate: 45deg;
  translate: -212.13px 0;
  outline: 0 solid #9932CC;
  z-index: 9;
}

#color3:hover {
  translate: 0 0;
  rotate: 0deg;
  z-index: 99;
  outline: 20px solid #9932CC;
}

#color4 {
  background: #BA55D3;
  rotate: 45deg;
  translate: 0 -212.13px;
  outline: 0 solid #BA55D3;
  z-index: 9;
}

#color4:hover {
  translate: 0 0;
  rotate: 0deg;
  z-index: 99;
  outline: 20px solid #BA55D3;
}

#color-code {
  position: absolute;
  top: 0;
  left: 0;
  width: 40px;
  height: 40px;
  translate: 130px 130px;
  border-radius: 20px;
  overflow: hidden;
  z-index: 199;
  opacity: 1;
  transition: 0.3s ease-in-out;
}

#color-code-bg {
  position: absolute;
  width: 40px;
  height: 40px;
  background-color: rgba(255, 255, 255, 0.8);
  filter: blur(10px);
}

#color-code-text {
  position: absolute;
  width: 40px;
  height: 40px;
  display: flex;
  justify-content: center;
  align-items: center;
}

#color-code-text::after {
  content: "v2";
  font-weight: 600;
  font-family: sans-serif;
  color: #1a1a1a;
}

#footer {
  height: 12%;
  width: 100%;
  background: white;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 1em;
  box-sizing: border-box;
  color: #bebebe;
}

#footer svg {
  scale: 0.75;
}

#footer #bookmarks {
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: smaller;
}
